import re

EMAIL = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")
CARD = re.compile(r"(?<!\d)(?:\d[ -]?){12,18}\d(?!\d)")
PHONE = re.compile(r"(?<!\d)(?:\+972[- ]?|0)5\d[- ]?\d{3}[- ]?\d{4}(?!\d)")


def luhn_ok(digits):
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0


def pseudonymize(text):
    mapping, labels, counts = {}, {}, {}

    def label(kind, value):
        key = (kind, value)
        if key not in labels:
            counts[kind] = counts.get(kind, 0) + 1
            labels[key] = f"{kind}_{counts[kind]}"
            mapping[labels[key]] = value
        return labels[key]

    def card_sub(m):
        digits = re.sub(r"\D", "", m.group())
        return label("CARD", digits) if luhn_ok(digits) else m.group()

    text = EMAIL.sub(lambda m: label("EMAIL", m.group()), text)
    text = CARD.sub(card_sub, text)          # cards before phones
    text = PHONE.sub(lambda m: label("PHONE", re.sub(r"[- ]", "", m.group())), text)
    return text, mapping


if __name__ == "__main__":
    t = ("Dana (dana.levi@mail.com, 054-1234567) paid with 4580 1234 5678 9010? "
         "No: card 4111-1111-1111-1111. Call 0541234567. Order 1234567890123.")
    print(pseudonymize(t))
